use vstd::prelude::*;

verus! {

    // A pure specification of the diagonal value: 1.0 if i == j, else 0.0
    spec fn diag_val(i: int, j: int) -> f64 {
        if i == j { 1.0 } else { 0.0 }
    }

    // A concrete implementation that matches the spec
    fn diag_val(i: int, j: int) -> (result: f64)
        ensures
            result == diag_val(i, j),
    {
        if i == j {
            1.0
        } else {
            0.0
        }
    }

    // Build an n×n identity matrix of f64’s
    fn identity(n: usize) -> (result: Vec<Vec<f64>>)
        ensures
            // The outer vector has length n
            result@.len() == n as nat &&
            // Each row has length n
            forall |i: nat| i < n as nat
                ==> result@[i]@.len() == n &&
            // Matrix entries agree with the diagonal‐value spec
            forall |i: nat, j: nat| i < n as nat && j < n as nat
                ==> result@[i]@[j] == diag_val(i as int, j as int),
    {
        let mut matrix: Vec<Vec<f64>> = Vec::new();
        let mut i: usize = 0;
        // Build row by row
        while i < n
            invariant
                i <= n,
                matrix.len() == i,
                matrix@.len() == i as nat,
            decreases n - i,
        {
            let mut row: Vec<f64> = Vec::new();
            let mut j: usize = 0;
            // Build each row element by element
            while j < n
                invariant
                    j <= n,
                    row.len() == j,
                    row@.len() == j as nat,
                decreases n - j,
            {
                let v = diag_val(i as int, j as int);
                row.push(v);
                j += 1;
            }
            // Now row.len() == n
            assert(row.len() == n);
            matrix.push(row);
            i += 1;
        }
        // Now matrix.len() == n
        assert(matrix.len() == n);
        result = matrix;
    }

}

fn main() {
    // Example usage (no proof obligations here)
    let m = identity(3);
    assert(m.len() == 3);
    assert(m[0][0] == 1.0 && m[0][1] == 0.0 && m[0][2] == 0.0);
    assert(m[1][0] == 0.0 && m[1][1] == 1.0 && m[1][2] == 0.0);
    assert(m[2][0] == 0.0 && m[2][1] == 0.0 && m[2][2] == 1.0);
}

